    data=json.load(f)
records=data.get('records', [])
max_ac = -1
max_id = None
count=0
for r in records:
    if r.get('OwnerUserId')==16:
        count+=1
        ac = r.get('AnswerCount')
        if ac is None:
            ac = -1
        if isinstance(ac, str):
            try:
                ac = int(ac)
            except:
                ac = -1
        if ac>max_ac:
            max_ac=ac
            max_id=r.get('Id')
print(json.dumps({'matching_posts':count,'max_answercount':max_ac,'post_id':max_id}))

